/// Fetch every matching message page. Backward walks (no cursor or `before`)
/// start at the newest page and page toward older IDs; forward walks (`after`)
/// start at the oldest page after the cursor and page toward newer IDs.
/// Results are de-duplicated and returned in ascending message-ID order.
fn read_all(
    c: &Client,
    channel_id: &str,
    before: Option<String>,
    after: Option<String>,
    limit: u32,
) -> anyhow::Result<Vec<Message>> {
    use std::collections::BTreeMap;
    let forward = after.is_some();
    let mut cursor_before = before;
    let mut cursor_after = after;
    let mut collected: BTreeMap<String, Message> = BTreeMap::new();
    loop {
        let mut path = format!("/channels/{channel_id}/messages?limit={limit}");
        if let Some(v) = &cursor_before {
            path.push_str(&format!("&before={v}"));
        }
        if let Some(v) = &cursor_after {
            path.push_str(&format!("&after={v}"));
        }
        let page: Vec<Message> = c.get(&path)?;
        if page.is_empty() {
            break;
        }
        let mut fresh = 0;
        for message in &page {
            if !collected.contains_key(&message.id) {
                fresh += 1;
            }
            collected.insert(message.id.clone(), message.clone());
        }
        if page.len() < limit as usize {
            break;
        }
        if forward {
            let max = page.iter().map(|m| &m.id).max().expect("non-empty").clone();
            if let Some(prev) = &cursor_after {
                anyhow::ensure!(max > *prev, "Message pages stopped progressing");
            }
            anyhow::ensure!(fresh > 0, "Message pages stopped progressing");
            cursor_after = Some(max);
        } else {
            let min = page.iter().map(|m| &m.id).min().expect("non-empty").clone();
            if let Some(prev) = &cursor_before {
                anyhow::ensure!(min < *prev, "Message pages stopped progressing");
            }
            anyhow::ensure!(fresh > 0, "Message pages stopped progressing");
            cursor_before = Some(min);
        }
    }
