#[cfg(test)]
mod tests {
    use super::*;
    use clap::Parser;

    fn message(id: &str) -> Message {
        Message {
            id: id.to_string(),
            channel_id: "C".to_string(),
            author_id: "A".to_string(),
            content: "x".to_string(),
            reply_to: None,
            created_at: "2026-01-01T00:00:00Z".to_string(),
            edited_at: None,
            attachments: Vec::new(),
            objects: Vec::new(),
            reactions: Vec::new(),
            mention_ids: Vec::new(),
        }
    }

    fn collect_ascending(pages: Vec<Vec<Message>>) -> Vec<Message> {
        use std::collections::BTreeMap;
        let mut all: BTreeMap<String, Message> = BTreeMap::new();
        for page in pages {
            for m in page {
                all.insert(m.id.clone(), m);
            }
        }
        all.into_values().collect()
    }

    #[test]
    fn read_validation_rejects_bad_cursors_and_limits() {
        assert!(validate_read(50, None, None).is_ok());
        assert!(validate_read(0, None, None).is_err());
        assert!(validate_read(201, None, None).is_err());
        let good = "01JAAAAAAAAAAAAAAAAAAAAAAAAA";
        assert!(validate_read(50, Some(good), None).is_ok());
        assert!(validate_read(50, None, Some(good)).is_ok());
        assert!(validate_read(50, Some(good), Some(good)).is_err());
        assert!(validate_read(50, Some("short"), None).is_err());
    }

    #[test]
    fn read_all_parses_flag_and_validates_before_http() {
        let cli = Cli::try_parse_from(["den", "read", "general", "--all"]).unwrap();
        let Cmd::Read { all, limit, .. } = cli.cmd else {
            panic!("expected read")
        };
        assert!(all);
        assert_eq!(limit, 50);
        // Both cursors and out-of-range limits are rejected by the same helper
        // the command runs before any HTTP request.
        assert!(validate_read(0, None, None).is_err());
        assert!(validate_read(50, Some("01JAAAAAAAAAAAAAAAAAAAAAAAAA"), Some("01JBBBBBBBBBBBBBBBBBBBBBBBBB")).is_err());
    }

    #[test]
    fn collected_pages_dedup_and_sort_ascending() {
        let out = collect_ascending(vec![
            vec![message("03"), message("04")],
            vec![message("01"), message("02"), message("03")],
        ]);
        let ids: Vec<_> = out.iter().map(|m| m.id.as_str()).collect();
        assert_eq!(ids, vec!["01", "02", "03", "04"]);
    }
}

